let data = [];

let outputArray = {{.Get_All_Coupon_Code.output}};
for (let item of outputArray) {
    if (item.Rewards) {
        data.push(...item.Rewards);
    }
}


let filteredData = Object.values(
    data.reduce((acc, coupon) => {
        let couponCode = coupon.coupon_code;
        if (
            !acc[couponCode] || 
            (coupon.maximum_discount > acc[couponCode].maximum_discount)
        ) {
            acc[couponCode] = coupon; 
          }
        return acc;
    }, [])
);

filteredData;

let Items = {{.Trigger.cart}}
let n = Items.length;
let code = "{{.Trigger.coupon_code}}" ? "{{.Trigger.coupon_code}}": "";
let orderID = "{{.Trigger.order_id}}" ?"{{.Trigger.order_id}}" : "";
let txn_no = "{{.Trigger.transaction_no}}" ? "{{.Trigger.transaction_no}}" : "";
let payment_gateway = "{{.Trigger.payment_gateway}}";

const skuSet = new Set();
const catSet = new Set();


for (let i = 0; i < n; i++){
  Items[i].sku.split(',').map(item => skuSet.add(item.trim()));
  Items[i].category.split(',').map(item => catSet.add(item.trim()));
}

//SET => ARRAY
const skuArray = [...skuSet];
const catArray = [...catSet];


let cart_value = Items.reduce((sum , item)=> sum + item.MRP * item.quantity,0)

let result = 
  {
    coupon_code : code,
    orderId : orderID,
    categories: catArray,
    SKU: skuArray,
    payment_gateway: payment_gateway,
    cart_value: cart_value,
    txn_no : txn_no,
    cart:Items,
  };

result;
